class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def plusOne(digits):
    dummy = ListNode(0, build(digits))
    last = dummy
    cur = dummy.next
    while cur:
        if cur.val != 9:
            last = cur
        cur = cur.next
    last.val += 1
    cur = last.next
    while cur:
        cur.val = 0
        cur = cur.next
    return dump(dummy if dummy.val else dummy.next)
